PREFIX schema: <https://schema.org/> PREFIX aw: <https://w3id.org/agentweb-testbed#>
SELECT ?name ?pname ?rate ?apr ?term ?type ?pay ?close ?amt WHERE {
?p a schema:MortgageLoan; schema:name ?name; schema:provider ?pr; schema:interestRate ?rate; schema:loanTerm ?t; aw:rateType ?type; aw:estimatedMonthlyPayment ?pm; aw:estimatedClosingCosts ?cc; aw:exampleLoanAmount ?am.
?pr schema:name ?pname. ?t schema:value ?term. ?pm schema:value ?pay. ?cc schema:value ?close. ?am schema:value ?amt.
OPTIONAL {?p schema:annualPercentageRate ?apr}
FILTER(?term=30 && ?type="fixed" && ?rate<=7.5 && ?pay<=3600 && ?close<=14500 && ?amt=440000)
} ORDER BY ?rate LIMIT 15

